SELECT T0."DocNum", T0."U_MESTS", T0."U_MEPSDT", T0."U_METWHSCD", T0."U_METWHSNM" as "RequestedBy",T0."CreateTime" FROM "@ME_STR"  T0 WHERE T0."U_MEFWHSCD" ='HO' AND T0."U_MESTS"='Open' and T0."CreateDate"=CURRENT_DATE and LEFT(LPAD(T0."CreateTime",6,'0'),4)>=TO_CHAR(ADD_SECONDS(CURRENT_TIMESTAMP,-60), 'HH24MI')
